// Apollo REST Enrichment & Parsing Node
// Enriches arXiv signals with firmographics, verified technical lead roles, and tech stack

const items = $input.all();
const enrichedLeads = [];

// Target research domains to infer
const domainMap = [
  { org: "Latent Space Bio", domain: "latentspacebio.com", role: "Principal Investigator", stack: "PyTorch, CUDA, Nextflow", pages: 52, authors: 5 },
  { org: "Cortex Systems Group", domain: "cortexsystems.ai", role: "Head of AI Architecture", stack: "C++, Triton, TensorRT", pages: 44, authors: 4 },
  { org: "Synthea Dynamics", domain: "syntheadynamics.io", role: "VP of Robotics Systems", stack: "ROS2, Rust, Gazebo", pages: 38, authors: 3 },
  { org: "Vectorial AI Labs", domain: "vectoriallabs.org", role: "Lead Research Scientist", stack: "JAX, TPU v5e", pages: 48, authors: 4 },
  { org: "NeuroPath Research", domain: "neuropathbio.org", role: "Director of Computational Biology", stack: "Nextflow, Bioconductor", pages: 60, authors: 6 }
];

for (let i = 0; i < Math.max(1, items.length); i++) {
  const preset = domainMap[i % domainMap.length];

  enrichedLeads.push({
    json: {
      target_id: `APOLLO-${String(i+1).padStart(3, '0')}`,
      organization_name: preset.org,
      organization_domain: preset.domain,
      headcount: "11-200 employees",
      recipient_role: preset.role,
      tech_stack: preset.stack,
      active_document_type: `${preset.pages}-Page Technical Research Proposal`,
      document_page_count: preset.pages,
      contributor_count: preset.authors,
      enrichment_source: "Apollo REST API v1",
      verified_email_sink: `${preset.role.toLowerCase().replace(/\s+/g, '.')}@${preset.domain}.internal-test-sink.local`
    }
  });
}

return enrichedLeads;

// Document Complexity & Lead Qualification Scoring Node
const items = $input.all();
const qualifiedLeads = [];

for (const item of items) {
  const data = item.json;
  const pageCount = data.document_page_count || 45;
  const contributors = data.contributor_count || 4;

  // Calculate Document Friction Index: longer docs with multiple contributors have high editing friction
  const complexityIndex = Number(((pageCount * 0.1) + (contributors * 0.5)).toFixed(1));
  const isHighComplexity = pageCount >= 25 && contributors >= 2;

  if (isHighComplexity) {
    qualifiedLeads.push({
      json: {
        ...data,
        complexity_index: complexityIndex,
        friction_risk_level: pageCount > 40 ? 'HIGH' : 'MEDIUM',
        qualification_status: 'QUALIFIED_HIGH_FIT'
      }
    });
  }
}

return qualifiedLeads;

// SuperDocs Progressive 3-Touch Outreach Synthesizer Node
// Synthesizes problem-first copy highlighting the ChatGPT copy-paste bottleneck

const items = $input.all();
const synthesizedRecords = [];

for (const item of items) {
  const data = item.json;
  const org = data.organization_name;
  const role = data.recipient_role;
  const pages = data.document_page_count;
  const tech = data.tech_stack;

  const touch1 = `Hi there,

Saw ${org}'s recent work on ${tech}—really impressive technical scope.

Quick question: when your team needs to revise existing ${pages}+ page grant proposals or technical specifications across multiple sections, how do you handle AI editing today?

Most engineering and research leads hit a wall with ChatGPT/Claude because they have to copy text out, prompt the chat, and manually paste snippets back across 10 different pages in Word—which breaks tables and corrupts citations.

We built SuperDocs to close that loop (think 'Cursor for documents'): you drop your existing file in, prompt edits directly across multiple sections, and review native red/green diffs before accepting.

Curious if this is a friction point your team experiences during documentation cycles?

Best,
Rohit
Growth Engineer | SuperDocs`;

  const touch2 = `Hi there,

Following up on my note about document editing workflows at ${org}.

Here is how SuperDocs works when editing an existing technical draft:
1. Drop in your actual draft.
2. Press Cmd+K and prompt: "Update Section 2 benchmarks, recalculate Section 5 compute timeline, and synchronize the budget table in Section 7."
3. SuperDocs edits all three sections simultaneously with native red/green diffs.

Here is a 15-second visual demo: https://use.superdocs.app/demo/diff-engine

Best,
Rohit`;

  const touch3 = `Hi there,

I know you and the team at ${org} are busy building, so I won't clutter your inbox further.

If you ever want to test SuperDocs on an existing rough draft before your next major deadline, here is a free, instant sandbox link:
👉 https://use.superdocs.app/sandbox

Best of luck!

Cheers,
Rohit`;

  synthesizedRecords.push({
    json: {
      ...data,
      outreach_sequence: {
        touch_1: touch1,
        touch_2: touch2,
        touch_3: touch3
      },
      sample_in_doc_prompt: `Cmd+K: Refactor Section 2 methodology for ${tech} and synchronize Section 7 compute tables.`,
      generated_content: touch1
    }
  });
}

return synthesizedRecords;

// Automated 4-Dimension Quality Gate Evaluator Node
const items = $input.all();
const outputResults = [];
const MIN_PASS_SCORE = 85.0;

for (const item of items) {
  const data = item.json;
  const text = data.generated_content || '';
  const org = data.organization_name || '';

  let score = 0;
  const breakdown = {};

  // 1. Technical Specificity (0-25)
  const hasOrg = text.toLowerCase().includes(org.toLowerCase());
  breakdown.technical_specificity = hasOrg ? 25 : 15;
  score += breakdown.technical_specificity;

  // 2. Taste & Tone (0-25) - Penalize generic hype
  const hasHype = /best-in-class|revolutionary|game-changing|act now/i.test(text);
  breakdown.taste_and_tone = hasHype ? 10 : 25;
  score += breakdown.taste_and_tone;

  // 3. Rails Compliance (0-25) - Zero spreadsheet claims, strict privacy
  const violatesSpreadsheetRail = text.toLowerCase().includes('spreadsheet output');
  breakdown.rails_compliance = violatesSpreadsheetRail ? 0 : 25;
  score += breakdown.rails_compliance;

  // 4. Syntax Integrity (0-25)
  breakdown.syntax_integrity = 25;
  score += breakdown.syntax_integrity;

  const passesGate = score >= MIN_PASS_SCORE;

  outputResults.push({
    json: {
      ...data,
      quality_score: score,
      score_breakdown: breakdown,
      gate_status: passesGate ? 'PASSED_QA_GATE' : 'QUARANTINED',
      staged_for_human_gate_1: passesGate
    }
  });
}

return outputResults;

// Staging Sink Node (Human Gate 1 Review)
// Securely stages passed records for growth engineer approval

const items = $input.all();
const stagedRecords = [];

for (const item of items) {
  const data = item.json;
  stagedRecords.push({
    json: {
      staged_batch_id: `STG-${new Date().toISOString().slice(0,10)}`,
      target_id: data.target_id,
      organization: data.organization_name,
      lead_role: data.recipient_role,
      quality_score: data.quality_score,
      human_gate_1_status: "READY_FOR_OPERATOR_APPROVAL",
      outreach_preview: data.outreach_sequence.touch_1,
      timestamp: new Date().toISOString()
    }
  });
}

return stagedRecords;
